#include "reconstruction/reconstruction_service.hpp"
#include <opencv2/core.hpp>
#include <opencv2/imgcodecs.hpp>
#include <cassert>
#include <filesystem>
#include <fstream>
int main(){namespace fs=std::filesystem;auto root=fs::temp_directory_path()/"tooth_reconstruction_test";fs::remove_all(root);fs::create_directories(root/"decode/left");fs::create_directories(root/"decode/right");std::ofstream(root/"decode/metadata.json")<<"{\"version\":\"0.1.0\",\"image_width\":4,\"image_height\":2,\"projector_width\":8,\"projector_height\":4}";cv::Mat lx(2,4,CV_32S,cv::Scalar(-1)),ly(2,4,CV_32S,cv::Scalar(-1)),rx=lx.clone(),ry=ly.clone(),mask(2,4,CV_8U,cv::Scalar(0));lx.at<int>(0,2)=1;ly.at<int>(0,2)=1;rx.at<int>(0,1)=1;ry.at<int>(0,1)=1;mask.at<uchar>(0,2)=255;auto write=[&](const fs::path&p,const char*k,const cv::Mat&m){cv::FileStorage f(p.string(),cv::FileStorage::WRITE);f<<k<<m;};write(root/"decode/left/projector_x.yml","projector_x",lx);write(root/"decode/left/projector_y.yml","projector_y",ly);write(root/"decode/right/projector_x.yml","projector_x",rx);write(root/"decode/right/projector_y.yml","projector_y",ry);cv::imwrite((root/"decode/left/valid_mask.png").string(),mask);cv::Mat rmask=mask.clone();rmask.setTo(0);rmask.at<uchar>(0,1)=255;cv::imwrite((root/"decode/right/valid_mask.png").string(),rmask);cv::FileStorage c((root/"stereo.yml").string(),cv::FileStorage::WRITE);cv::Mat K=(cv::Mat_<double>(3,3)<<100,0,1.5,0,100,.5,0,0,1),D=cv::Mat::zeros(1,5,CV_64F),R=cv::Mat::eye(3,3,CV_64F),T=(cv::Mat_<double>(3,1)<<-10,0,0);c<<"K1"<<K<<"D1"<<D<<"K2"<<K<<"D2"<<D<<"R"<<R<<"T"<<T<<"image_width"<<4<<"image_height"<<2;c.release();reconstruction::ReconstructionService s;reconstruction::ReconstructionInput in{root/"decode",root/"stereo.yml",{2.0,{},{}}};auto v=s.validate(in);assert(v.valid&&v.reconstructable_point_count==1);auto out=root/"cloud.ply";auto q=s.reconstruct({in,out,false});assert(q.ok&&q.point_count==1&&fs::exists(out));auto conflict=s.reconstruct({in,out,false});assert(!conflict.ok&&conflict.error->code=="output_file_exists");}
